setup.script:
#!/bin/sh
echo "claude $* cfg=${CLAUDE_CONFIG_DIR:-}" >> "$DIFFTEST_FAKELOG"
case "$1 $2" in
  "auth status") case "${CLAUDE_CONFIG_DIR:-}" in *work|"") echo '{"loggedIn":true}'; exit 0;; *other) echo '{"loggedIn":false}'; exit 0;; *) exit 1;; esac ;;
esac
exit 0

#!/bin/sh
echo "codex $* home=${CODEX_HOME:-}" >> "$DIFFTEST_FAKELOG"
case "$1 $2" in
  "login status") case "${CODEX_HOME:-}" in *b) echo 'Logged in'; exit 0;; *) echo 'Not logged in'; exit 1;; esac ;;
esac
exit 0

